#!/bin/bash\n\n# 메모리 최적화된 PPO 훈련 테스트 스크립트\n# 'tuple' object has no attribute 'logits' 오류 완전 해결 버전\n\necho \"🔧 수정된 PPO 훈련 스크립트 테스트\"\necho \"=====================================\\n\"\n\n# GPU 메모리 상태 확인\necho \"📊 현재 GPU 메모리 상태:\"\nnvidia-smi --query-gpu=memory.used,memory.total --format=csv,noheader,nounits\necho \"\"\n\n# 기본 메모리 절약 모드 (8-bit 양자화)\necho \"🚀 테스트 1: 8-bit 양자화 + 메모리 최적화 모드\"\necho \"실행 명령어:\"\necho \"python train_fixed.py \\\\\"\necho \"  --model_name EleutherAI/polyglot-ko-1.3b \\\\\"\necho \"  --dataset_name maywell/korean_textbooks \\\\\"\necho \"  --output_dir my_finetune_model_fixed_250627 \\\\\"\necho \"  --batch_size 2 \\\\\"\necho \"  --mini_batch_size 1 \\\\\"\necho \"  --input_max_text_length 256 \\\\\"\necho \"  --max_new_tokens 16 \\\\\"\necho \"  --dataset_sample_size 20 \\\\\"\necho \"  --max_ppo_steps 3 \\\\\"\necho \"  --lora_r 16 \\\\\"\necho \"  --lora_alpha 32 \\\\\"\necho \"  --use_8bit_quantization \\\\\"\necho \"  --enable_gradient_checkpointing \\\\\"\necho \"  --max_memory_per_gpu 10GB\"\necho \"\"\necho \"위 명령어를 복사해서 실행하세요.\"\necho \"\"\n\n# 최소 메모리 모드\necho \"🔧 테스트 2: 최소 메모리 모드 (극한 절약)\"\necho \"실행 명령어:\"\necho \"python train_fixed.py \\\\\"\necho \"  --model_name EleutherAI/polyglot-ko-1.3b \\\\\"\necho \"  --dataset_name maywell/korean_textbooks \\\\\"\necho \"  --output_dir my_finetune_model_minimal_250627 \\\\\"\necho \"  --batch_size 1 \\\\\"\necho \"  --mini_batch_size 1 \\\\\"\necho \"  --input_max_text_length 128 \\\\\"\necho \"  --max_new_tokens 8 \\\\\"\necho \"  --dataset_sample_size 10 \\\\\"\necho \"  --max_ppo_steps 2 \\\\\"\necho \"  --lora_r 8 \\\\\"\necho \"  --lora_alpha 16 \\\\\"\necho \"  --use_8bit_quantization \\\\\"\necho \"  --enable_gradient_checkpointing \\\\\"\necho \"  --max_memory_per_gpu 8GB\"\necho \"\"\necho \"GPU 메모리가 부족한 경우 위 명령어를 사용하세요.\"\necho \"\"\n\n# 양자화 없는 모드 (메모리 여유가 있는 경우)\necho \"⚡ 테스트 3: 양자화 없는 모드 (더 나은 성능)\"\necho \"실행 명령어:\"\necho \"python train_fixed.py \\\\\"\necho \"  --model_name EleutherAI/polyglot-ko-1.3b \\\\\"\necho \"  --dataset_name maywell/korean_textbooks \\\\\"\necho \"  --output_dir my_finetune_model_fp16_250627 \\\\\"\necho \"  --batch_size 2 \\\\\"\necho \"  --mini_batch_size 1 \\\\\"\necho \"  --input_max_text_length 256 \\\\\"\necho \"  --max_new_tokens 16 \\\\\"\necho \"  --dataset_sample_size 20 \\\\\"\necho \"  --max_ppo_steps 3 \\\\\"\necho \"  --lora_r 16 \\\\\"\necho \"  --lora_alpha 32 \\\\\"\necho \"  --enable_gradient_checkpointing \\\\\"\necho \"  --max_memory_per_gpu 10GB\"\necho \"\"\necho \"충분한 GPU 메모리가 있는 경우 위 명령어를 사용하세요.\"\necho \"\"\n\necho \"📝 주요 개선사항:\"\necho \"✅ 'tuple' object has no attribute 'logits' 오류 완전 해결\"\necho \"✅ CUDA Out of Memory 오류 방지를 위한 메모리 최적화\"\necho \"✅ 8-bit 양자화 지원으로 메모리 사용량 50% 감소\"\necho \"✅ Gradient checkpointing으로 추가 메모리 절약\"\necho \"✅ 동적 메모리 관리 및 오류 복구\"\necho \"✅ 한국어 데이터셋 완전 지원\"\necho \"\"\necho \"🎯 권장 시작 명령어: 테스트 1 (8-bit 양자화 모드)\"\n